import csv
import hashlib


def _parse_csv_rows(filepath):
    with open(filepath, newline='') as fh:
        return list(csv.DictReader(fh))


def _validate_row(row, existing_emails, role_map):
    email = row.get('email', '').strip().lower()
    if not email or '@' not in email:
        return None, 'invalid email'
    if email in existing_emails:
        return None, 'duplicate'
    raw_password = row.get('password', '')
    if len(raw_password) < 8:
        return None, 'password too short'
    role_name = row.get('role', 'viewer').strip()
    if role_name not in role_map:
        return None, f'unknown role {role_name}'
    return email, None


def _build_user(row, email, role_map):
    password_hash = hashlib.sha256(row['password'].encode()).hexdigest()
    return {'email': email, 'password_hash': password_hash, 'role_id': role_map[row.get('role', 'viewer').strip()]}


def _build_welcome_email(email):
    return {'to': email, 'subject': 'Welcome!', 'body': f'Hi {email}, your account is ready.'}


def import_users_from_csv(filepath, existing_emails, role_map, send_welcome):
    results = {'imported': [], 'skipped': [], 'errors': [], 'emails': []}
    for row in _parse_csv_rows(filepath):
        email, error = _validate_row(row, existing_emails, role_map)
        if error == 'duplicate':
            results['skipped'].append(row.get('email', '').strip().lower())
            continue
        if error:
            results['errors'].append({'row': row, 'reason': error})
            continue
        user = _build_user(row, email, role_map)
        results['imported'].append(user)
        if send_welcome:
            results['emails'].append(_build_welcome_email(email))
    return results
